),

t4 as (
    select
        coalesce(nullif('OMNI_INWARD:' || nullif(trim(OMNI_INWARD_NO),''), 'OMNI_INWARD:'), md5(normalise(upper(nullif(trim(REPORT_ATTACH_PATH),''))))) as HUB_DOCUMENT_BK__OMNI_INWARD_OMNI_INWARD_NO_REPORT_ATTACH_PATH,
