        remedinet_provider_code as HUB_AGREEMENT_BK__REMEDINET_PROVIDER_CODE,
        claim_no as HUB_CLAIM_BK__CLAIM_NO,
        omni_inward_no as HUB_DOCUMENT_BK__OMNI_INWARD_NO,
