    qualify row_number() over (partition by HUB_CLAIM_BK__CLID, HUB_DISTRIBUTION_CHANNEL_BK__IMD_CODE, HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO, HUB_FINANCIAL_TRANSACTION_BK__UTR_NO, HUB_LOSS_EVENT_BK__CLAIM_NO, HUB_PARTY_BK__HOSPITAL_ID, HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO, HUB_POLICY_BK__POLICY, dr_requirement_insured order by HUB_CLAIM_BK__CLID, HUB_DISTRIBUTION_CHANNEL_BK__IMD_CODE, HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO, HUB_FINANCIAL_TRANSACTION_BK__UTR_NO, HUB_LOSS_EVENT_BK__CLAIM_NO, HUB_PARTY_BK__HOSPITAL_ID, HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO, HUB_POLICY_BK__POLICY, dr_requirement_insured) = 1
