    coalesce(t3.HUB_LOSS_EVENT_BK__CLAIM_ID, t8.HUB_LOSS_EVENT_BK__CLAIM_NO, t9.HUB_LOSS_EVENT_BK__TPA_CLAIM_NO) as HUB_LOSS_EVENT_BK,
