    t5.HUB_PARTY_BK__PAYER_CODE as T5__HUB_PARTY_BK__PAYER_CODE,
    t5.HUB_PARTY_BK__REMEDINET_PROVIDER_CODE as T5__HUB_PARTY_BK__REMEDINET_PROVIDER_CODE,
    t8.HUB_LOCATION_BK__LOCATION_CODE as T8__HUB_LOCATION_BK__LOCATION_CODE,
    t8.HUB_LOCATION_BK__LOCATIONCODE as T8__HUB_LOCATION_BK__LOCATIONCODE,
    t8.HUB_LOCATION_BK__ORPHAN_LOC as T8__HUB_LOCATION_BK__ORPHAN_LOC,
    t8.HUB_LOCATION_BK__POLICY_LOCATION as T8__HUB_LOCATION_BK__POLICY_LOCATION,
    t8.HUB_LOCATION_BK__RISK_LOCATION as T8__HUB_LOCATION_BK__RISK_LOCATION,
    t9.HUB_ORG_UNIT_BK__CONTROLLING_OFFICE as T9__HUB_ORG_UNIT_BK__CONTROLLING_OFFICE,
    t9.HUB_ORG_UNIT_BK__OPERATING_OFFICE as T9__HUB_ORG_UNIT_BK__OPERATING_OFFICE,
    t9.HUB_PARTY_BK__CUSTOMER_ID as T9__HUB_PARTY_BK__CUSTOMER_ID,
