    coalesce(t1.inward_no, t4.omni_inward_no, t3.inward_no) as DOCUMENT_REFERENCE_NUMBER,
    t3.doc_remark as DOCUMENT_REMARKS,
    t0.card_status as DOCUMENT_STATUS,
    coalesce(t4.attachment_type, t0.card_type) as DOCUMENT_TYPE,
    t0.card_expiry as EXPIRY_DATE,
    t6.faxcreateddate as ISSUE_DATE,
    t9.loss_date as LOSS_DATE,
    coalesce(t8.type_of_loss, t3.type_of_loss) as LOSS_EVENT_TYPE,
    t6.fax_no as ORIGINATING_FAX_NUMBER,
    t3.pod_no as PROOF_OF_DELIVERY_NUMBER,
    coalesce(t8.document_receive_date, t8.doc_receive_date_max, t3.doc_rec_date, t6.createddate) as RECEIVED_DATE,
    t5.is_document_received as RECEIVED_INDICATOR,
    t3.doc_rec_time as RECEIVED_TIME,
    t4.hos_ref_id as RELATED_PRE_AUTHORISATION_REFERENCE,
    coalesce(t8.dr_requirement_hospital, t8.dr_requirement_insured, t8.dr_requirement_others) as REQUIRED_DOCUMENT_TYPE,
