from t0
full outer join t1 on t1.HUB_DOCUMENT_BK__INWARD_NO = t0.HUB_DOCUMENT_BK__CARD_NO
full outer join t2 on t2.HUB_DOCUMENT_BK__OMNI_INWARD_NO = coalesce(t0.HUB_DOCUMENT_BK__CARD_NO, t1.HUB_DOCUMENT_BK__INWARD_NO)
full outer join t3 on t3.HUB_DOCUMENT_BK__INWARD_ID = coalesce(t0.HUB_DOCUMENT_BK__CARD_NO, t1.HUB_DOCUMENT_BK__INWARD_NO, t2.HUB_DOCUMENT_BK__OMNI_INWARD_NO)
full outer join t4 on t4.HUB_DOCUMENT_BK__OMNI_INWARD_OMNI_INWARD_NO_REPORT_ATTACH_PATH = coalesce(t0.HUB_DOCUMENT_BK__CARD_NO, t1.HUB_DOCUMENT_BK__INWARD_NO, t2.HUB_DOCUMENT_BK__OMNI_INWARD_NO, t3.HUB_DOCUMENT_BK__INWARD_ID)
full outer join t5 on t5.HUB_DOCUMENT_BK__OMNI_INWARD_NO = coalesce(t0.HUB_DOCUMENT_BK__CARD_NO, t1.HUB_DOCUMENT_BK__INWARD_NO, t2.HUB_DOCUMENT_BK__OMNI_INWARD_NO, t3.HUB_DOCUMENT_BK__INWARD_ID, t4.HUB_DOCUMENT_BK__OMNI_INWARD_OMNI_INWARD_NO_REPORT_ATTACH_PATH)
full outer join t6 on t6.HUB_DOCUMENT_BK__INWARD_INWARDNO = coalesce(t0.HUB_DOCUMENT_BK__CARD_NO, t1.HUB_DOCUMENT_BK__INWARD_NO, t2.HUB_DOCUMENT_BK__OMNI_INWARD_NO, t3.HUB_DOCUMENT_BK__INWARD_ID, t4.HUB_DOCUMENT_BK__OMNI_INWARD_OMNI_INWARD_NO_REPORT_ATTACH_PATH, t5.HUB_DOCUMENT_BK__OMNI_INWARD_NO)
full outer join t7 on t7.HUB_DISTRIBUTION_CHANNEL_BK__IMD_CODE = t0.HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID
full outer join t8 on t8.HUB_CLAIM_BK__CLID = coalesce(t1.HUB_CLAIM_BK__CASE_ID, t2.HUB_CLAIM_BK__CLAIM_ID, t3.HUB_CLAIM_BK__CLAIM_ID, t5.HUB_CLAIM_BK__CLAIM_NO)
full outer join t9 on t9.HUB_CLAIM_BK__BJAZ_CLAIM_ID = coalesce(t1.HUB_CLAIM_BK__CASE_ID, t2.HUB_CLAIM_BK__CLAIM_ID, t3.HUB_CLAIM_BK__CLAIM_ID, t5.HUB_CLAIM_BK__CLAIM_NO, t8.HUB_CLAIM_BK__CLID)
